package cn.zhuatech.meetingai.controller; import cn.zhuatech.meetingai.common.ApiResponse; import cn.zhuatech.meetingai.service.MeetingActionService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/ai") @PreAuthorize("hasAnyRole('DOMAIN_USER','DOMAIN_OPERATOR','ADMIN')") public class AiFeatureController { private final MeetingActionService service; public AiFeatureController(MeetingActionService service){this.service=service;} @PostMapping("/meeting/analyze") public ApiResponse<MeetingActionService.Result> execute(@Valid @RequestBody MeetingActionService.Request request){return ApiResponse.ok("会议纪要与行动项分析完成",service.analyze(request));} }